(inst, def): void => {
  def.pattern ??= regexes.base64;
  $ZodStringFormat.init(inst, def);

  inst._zod.bag.contentEncoding = "base64";

  inst._zod.check = (payload) => {
    if (isValidBase64(payload.value)) return;

    payload.issues.push({
      code: "invalid_format",
      format: "base64",
      input: payload.value,
      inst,
      continue: !def.abort,
    });
  };
}

