  inst._zod.check = (payload) => {
    if (isValidBase64URL(payload.value)) return;

    payload.issues.push({
      code: "invalid_format",
      format: "base64url",
      input: payload.value,
      inst,
      continue: !def.abort,
    });
  };
}

